package com.bloodwoodhero;

import lombok.Getter;

/**
 * Where a bloodwood is in its cycle, and therefore what its next click does.
 *
 * <p>The three steps share a menu option, so nothing in the text tells them apart - a
 * click that collects a full bucket reads exactly like a click that chops. Only the
 * varbits know, which is why the label is worth drawing at all.</p>
 */
public enum BloodwoodStage
{
	/** Sap is draining into the bucket. Drawn beside the figure for how much is left. */
	TAPPING("TAP"),

	/** The bucket is full: the next click collects it, and is not a chop. */
	COLLECT("COLLECT"),

	/** Nothing left to take. The next click starts the chopping cycle. */
	CHOP("CHOP");

	/** What to draw on the tree. Every stage names itself; only where differs. */
	@Getter
	private final String label;

	BloodwoodStage(String label)
	{
		this.label = label;
	}
}

